UITrophyExplosionFragmentSprite=function(game,prefix,addNumericSuffix,numFragments){var randomFragmentIndex='';if(addNumericSuffix){randomFragmentIndex=Math.floor(Math.random()*numFragments);}Phaser.Sprite.call(this,game,0,0,'celebration',prefix+randomFragmentIndex);this.game.physics.p2.enable(this);this.body.allowSleep=false;this.body.onBeginContact.add(this._hitSomething,this);this.body.clearShapes();this.body.loadPolygon('celebration-physics',prefix+randomFragmentIndex);this.body.setMaterial(UIUtils.trophyFragmentMaterial);this.body.setCollisionGroup(UIUtils.trophyFragmentCollisionGroup);this.body.collides([UIUtils.gameFloorCollisionGroup]);this.body.collideWorldBounds=false;this.kill();};UITrophyExplosionFragmentSprite.prototype=Object.create(Phaser.Sprite.prototype);UITrophyExplosionFragmentSprite.prototype.constructor=UITrophyExplosionFragmentSprite;UITrophyExplosionFragmentSprite.prototype.update=function(){if(!this.exists){return;}if(this.fading){this.alpha=Math.max(0.0,this.alpha-0.025);}if(this.alpha==0.0){this.kill();}};UITrophyExplosionFragmentSprite.prototype.spawn=function(x,y,width,height,randomizeRotation){var speed=UIConstants.TROPHY_FRAGMENT_MIN_SPEED+Math.random()*(UIConstants.TROPHY_FRAGMENT_MAX_SPEED-UIConstants.TROPHY_FRAGMENT_MIN_SPEED);var direction=UIConstants.TROPHY_FRAGMENT_MIN_ANGLE+Math.random()*(UIConstants.TROPHY_FRAGMENT_MAX_ANGLE-UIConstants.TROPHY_FRAGMENT_MIN_ANGLE);var dirX=Math.cos(direction);var dirY=Math.sin(direction);var speedX=dirX*speed;var speedY=dirY*speed;x+=Math.random()*dirX*width;y+=Math.random()*dirY*height;this.reset(x,y);this.alpha=1.0;if(randomizeRotation){this.body.rotation=Math.random()*Math.PI*2.0;}this.body.velocity.x=speedX;this.body.velocity.y=speedY;this.body.angularVelocity=Math.random()*UIConstants.TROPHY_FRAGMENT_MAX_ROTATION_SPEED-UIConstants.TROPHY_FRAGMENT_MAX_ROTATION_SPEED/2.0;this.fading=false;};UITrophyExplosionFragmentSprite.prototype.retire=function(){this.kill();};UITrophyExplosionFragmentSprite.prototype._hitSomething=function(body,shapeA,shapeB,equation){this.fading=true;};